@source_precision
def chart(self, chart, Z, coordinate, log_tau='-1', theta=None, viscosity='1'):
    self.assert_graph()
    c = self.ctx
    v = c.mpf(coordinate)
    mu = c.mpf(self.pulse.mu)
    if chart == 'early_y':
        if endpoints(v)[0] < 0 or endpoints(v)[1] > 1:
            raise ValueError('Early original y[0,1] required')
        xi = mu * v
        internal = 'pulse_entrance'
    elif chart == 'O3_power':
        if endpoints(v)[0] < 0 or endpoints(v)[1] > 1:
            raise ValueError('Whole original O3 power phase[0,1] required')
        if not all((mp.isfinite(x) for x in endpoints(v))):
            raise ValueError('Finite power phase required')
        result = self.actual_power(Z, v, log_tau, theta, viscosity)
        result.update(chart=chart, coverage_coordinate=v, all_nonzero_incoming_histories_and_radial_remainder_retained=True)
        return result
    elif chart == 'pulse_entrance':
        xi = v
        internal = chart
    else:
        raise ValueError('Current entrance or actual O3 power chart required')
    result = self.exporter(self.main_tensor, internal, Z, xi, log_tau, theta, viscosity)
    data = self.main_tensor._data(c.mpf(Z))
    Bh = result['source_full_main_exit_history_rows']['Bh']
    if internal == 'pulse_entrance':
        partial = gp_energy(c, xi, None, self.main_tensor.cells)
        forward = forward_entrance_energy_rows(c, mu, xi, data['ap'], data['incoming_energy'], partial, Bh)
        result.update(original_partial_entrance_energy_bound=partial, current_forward_anchored_full_energy_rows=forward, selected_forward_backward_energy_same_source_not_two_added_terms=True)
    result.update(chart=chart, coverage_coordinate=v, source_xi=xi, original_ordinary_y_coordinate='mu*early_y or xi=mu*y for entrance;xi=-mu*Tw*(1-phase) for O3 power', all_nonzero_incoming_histories_and_radial_remainder_retained=True, actual_full_upstream_power_not_only_unit_left_neighborhood=internal == 'O3_power', **dict.fromkeys(OPEN, False))
    return result

