@source_precision
def angular(self, Z, offset, log_tau='-1', theta=None, viscosity='1'):
    self.assert_graph()
    c = self.ctx
    Z = c.mpf(Z)
    v = c.mpf(offset)
    lt = c.mpf(log_tau)
    nu = c.mpf(viscosity)
    if not all((mp.isfinite(x) for x in endpoints(Z) + endpoints(v))) or endpoints(Z)[0] < -1 or endpoints(Z)[1] > 1 or (endpoints(v)[0] < -4) or (endpoints(v)[1] > 0):
        raise ValueError('Actual angular region Z[-1,1], s[-4,0] required')
    if endpoints(nu)[0] <= 0 or not all((mp.isfinite(x) for x in endpoints(nu) + endpoints(lt))):
        raise ValueError('Finite compact log(tau) and finite constant nu>0 required')
    if theta is not None and (not all((mp.isfinite(x) for x in endpoints(c.mpf(theta))))):
        raise ValueError('Finite theta or all-angle enclosure required')
    native = self.outer.angular(Z, v)
    data = self.outer.data(Z)
    future = angular_future_changes(self.outer, data, v)
    post = self.post_pressure(Z)
    full_rows = normalized_full_moment_rows(self.heat, self.outer, native, data, future, post, v, c)
    A, E, P, K = (full_rows[name] for name in ('A', 'E', 'P', 'K'))
    one = IntervalTaylor.constant(c, 1, 5)
    q = -self.history.steep.wait - self.history.steep.Ts - 2 + v
    logR, radius_source = self.physical.radius('outer_angular', v, {}, self.outer)
    caplog = c.ln(c.mpf(endpoints(self.heat.Scap)[1])) - q
    if endpoints(caplog + logR)[0] < 0:
        raise ValueError('Angular inverse-radius cap does not enclose the same exact radius')
    cap = c.exp(c.mpf(endpoints(caplog)[1]))
    inverseR = c.mpf([0, endpoints(cap)[1]])
    local_heat = copy.copy(self.heat)
    local_heat.S = inverseR
    local_heat.ctx = c
    full = dict(angular_defect_rows=A, energy_defect_rows=E, pressure_defect_rows=P, K_defect_rows=K)
    stress = collar_stress_rows(local_heat, dict(K_rows=K), full, Z, c.mpf(0))
    grids = {name: ordinary_grid(stress[name], 3) for name in ('theta', 'axial', 'theta_inertial', 'theta_shear')}
    parts = angular_source_log_parts(self.physical, v)
    beta = -2 - self.heat.delta
    ps = {}
    div = {}
    for name, factor in (('theta', 'Qtheta'), ('axial', 'Qz')):
        ps[name] = {}
        div[name] = {}
        for i in range(4):
            for j in range(4 - i):
                bracket = physical_bracket(c, grids[name], i, j, Z, self.heat.delta, beta)
                ps[name]['r%d_z%d' % (i, j)] = physical_source_row(c, bracket, parts[factor], beta - i + j * (self.heat.delta - 1), lt, nu, i + j, c.mpf(i) / 2 * (c.ln(2) - logR))
        for i in range(3):
            for j in range(3 - i):
                bracket = physical_bracket(c, grids[name], i + 1, j, Z, self.heat.delta, beta)
                for m in range(i + 1):
                    bracket += physical_bracket(c, grids[name], i - m, j, Z, self.heat.delta, beta) * ((2 if name == 'theta' else 1) * math.comb(i, m) * (-1) ** m * math.factorial(m) / c.mpf(2) ** (m + 1))
                div[name]['r%d_z%d' % (i, j)] = physical_source_row(c, bracket, parts[factor], beta - 1 - i + j * (self.heat.delta - 1), lt, nu, i + j, c.mpf(i + 1) / 2 * (c.ln(2) - logR), nu_base=c.mpf('.5'))
    diagonal = {}
    error = {}
    for i in range(3):
        for j in range(3 - i):
            bracket = physical_bracket(c, grids['axial'], i, j + 1, Z, self.heat.delta, beta)
            if i:
                bracket += physical_bracket(c, grids['axial'], i - 1, j + 1, Z, self.heat.delta, beta) * (c.mpf(i) / 2)
            diagonal['r%d_z%d' % (i, j)] = physical_source_row(c, bracket, parts['completed_diagonal'], beta + self.heat.delta - i + j * (self.heat.delta - 1), lt, nu, i + j, c.mpf(i) / 2 * (c.ln(2) - logR))
            error['r%d_z%d' % (i, j)] = physical_source_row(c, -collar_velocity_bracket(c, K, i, j + 2, Z, self.heat.delta), parts['B'], -1 - self.heat.delta - i + (j + 2) * (self.heat.delta - 1), lt, nu, i + j, c.mpf(i) / 2 * (c.ln(2) - logR), nu_base=c.mpf('.5'))
    cs = sn = c.mpf([-1, 1]) if theta is None else None
    if theta is not None:
        cs = c.cos(c.mpf(theta))
        sn = c.sin(c.mpf(theta))
    tt = ps['theta']['r0_z0']
    tz = ps['axial']['r0_z0']
    dd = diagonal['r0_z0']
    er = error['r0_z0']
    zero = physical_source_row(c, c.mpf(0), parts['B'], -1 - self.heat.delta, lt, nu, 0)
    tensor = dict(xx=[scale_row(c, tt, -2 * cs * sn), scale_row(c, dd, sn * sn)], xy=[scale_row(c, tt, cs * cs - sn * sn), scale_row(c, dd, -cs * sn)], xz=[scale_row(c, tz, cs)], yy=[scale_row(c, tt, 2 * cs * sn), scale_row(c, dd, cs * cs)], yz=[scale_row(c, tz, sn)], zz=[zero])
    divcart = dict(x=[scale_row(c, div['theta']['r0_z0'], -sn)], y=[scale_row(c, div['theta']['r0_z0'], cs)], z=[div['axial']['r0_z0']])
    ecart = dict(x=[scale_row(c, er, -sn)], y=[scale_row(c, er, cs)], z=[zero])
    residual = {name: [scale_row(c, row, -1) for row in divcart[name]] + ecart[name] for name in ('x', 'y', 'z')}
    pressure_rows = [-sum((P[n] * math.comb(j, n) * (-self.heat.prate) ** (j - n) for n in range(j + 1)), one * 0) for j in range(5)]
    return dict(Z=Z, angular_offset=v, log_tau=lt, viscosity=nu, current_actual_normalized_full_moment_rows=dict(A=A, E=E, P=P, K=K), current_normalized_post_pressure_source=post, current_signed_remaining_angular_quadratic_kernels=future, current_actual_normalized_stress_mixed3=grids, physical_cylindrical_stress_mixed3=ps, physical_stress_divergence_mixed2=div, completed_theta_theta_stress_mixed2=diagonal, physical_axial_viscosity_remainder_mixed2=error, completed_background_tensor_cartesian_components=tensor, physical_completed_stress_divergence_cartesian=divcart, physical_remainder_cartesian=ecart, physical_momentum_residual_decomposition_cartesian=residual, stable_actual_absolute_pressure_mixed4_factored=ordinary_grid(pressure_rows, 4), original_forward_absolute_pressure_Taylor=native['pressure_over_Pstar_squared_Taylor'], original_current_energy_Taylor=native['energy_Taylor'], normalized_energy_native_consistency=E[0] - K[0] * K[0] * copy_jet(c, native['energy_Taylor']) * 2, exact_current_positive_log_source_parts=parts, exact_source_logR=logR, radius_source=radius_source, inverse_radius_enclosure=inverseR, inverse_radius_exact_source='1/R=S_exact*exp(-q), q=-wait-Ts-2+s', inverse_radius_cap_only_not_exact_field_value=True, exact_pure_swirl_meridional_velocity_radial_divergence_and_remainder_zero=True, actual_pressure_is_same_P0_Pin_forward_function_by_current_Cp_zero=True, actual_full_stress_not_local_difference=True, original_full_nonzero_A_E_P_and_signed_C5_controls_retained=True, regional_decomposition_is_not_global_temporal_flatness=True, **dict.fromkeys(OPEN, False))
